    {
      "key": "sections.complexity_confusion.title",
      "text": ""
    },
    {
      "key": "sections.complexity_confusion.caption",
      "text": ""
    },
    {
      "key": "durable_claims.0",
      "text": "{arm:brisk-s.few} satisfies all operational criteria, attaining {criteria.overall.brisk-s.few.value}% Balanced accuracy and {criteria.p95.brisk-s.few.value} p95 latency with {count.failing.cell_floor.brisk-s.few} failing cells."
    },
    {
      "key": "durable_claims.1",
      "text": "{arm:nano-xs.few} reaches {criteria.overall.nano-xs.few.value}% Balanced accuracy but drops to {criteria.cell_floor.nano-xs.few.complex.news.value}% on complex news turns."
    },
    {
      "key": "method.0.term",
      "text": "Evaluation design"
    },
    {
      "key": "method.0.text",
      "text": "Full factorial evaluation testing {count.arms|words} configurations across {count.cells|words} complexity and domain target matrix cells."
    },
    {
      "key": "method.1.term",
      "text": "Sample size"
    },
    {
      "key": "method.1.text",
      "text": "Evaluated across {scoreboard.brisk-s.few.cases} stratified dialogue turns sampled from production corpus distributions."
    },
    {
      "key": "method.2.term",
      "text": "Passing criteria"
    },
    {
      "key": "method.2.text",
      "text": "A turn passes only when predicted labels match ground truth for both complexity level and domain category."
    },
    {
      "key": "method.3.term",
      "text": "Operational gates"
    },
    {
      "key": "method.3.text",
      "text": "Requires Balanced accuracy at or above {criteria.overall.threshold}%, cell accuracy at or above {criteria.cell_floor.threshold}%, and p95 latency at or below {criteria.p95.threshold}."
    },
    {
      "key": "method.4.term",
      "text": "Cost basis"
    },
    {
      "key": "method.4.text",
      "text": "Calculated from observed token usage multiplied by standard vendor list prices per million turns."
    },
    {
      "key": "explore.title",
      "text": "Threshold sensitivity"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting the cell floor recalculates arm eligibility; setting the floor at or below {criteria.cell_floor.nano-xs.few.complex.news.value}% qualifies {arm:nano-xs.few}."
    },
    {
      "key": "explore.controls.cell_floor_threshold.title",
      "text": "Cell floor threshold"
    }
  ]
}

